,"parent":"300000","type":"Equity","normal":"Credit","kind":"Group"},{"code":"321001","name":"Retained Earnings","parent":"320000","type":"Equity","normal":"Credit","kind":"Posting"},{"code":"322001","name":"Current-Year Earnings","parent":"320000","type":"Equity","normal":"Credit","kind":"System"},{"code":"323001","name":"Approved Distributions","parent":"320000","type":"Equity","normal":"Debit","kind":"Posting"},{"code":"400000","name":"Revenue","parent":null,"type":"Revenue","normal":"Credit","kind":"Group"},{"code":"410000","name":"Service revenue","parent":"400000","type":"Revenue","normal":"Credit","kind":"Group"},{"code":"411001","name":"Influencer Campaign Revenue","parent":"410000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"412001","name":"Media Buying Revenue","parent":"410000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"413001","name":"Creative and Production Revenue","parent":"410000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"414001","name":"Management and Retainer Fees","parent":"410000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"415001","name":"Commission Revenue","parent":"410000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"420000","name":"Revenue deductions","parent":"400000","type":"Revenue","normal":"Credit","kind":"Group"},{"code":"421001","name":"Sales Discounts and Allowances","parent":"420000","type":"Revenue","normal":"Debit","kind":"Posting"},{"code":"500000","name":"Direct costs","parent":null,"type":"Expense","normal":"Debit","kind":"Group"},{"code":"510000","name":"Campaign delivery","parent":"500000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"511001","name":"Creator and Influencer Costs","parent":"510000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"512001","name":"Media Placement Costs","parent":"510000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"513001","name":"Production Costs","parent":"510000