630000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"632001","name":"Bank Charges","parent":"630000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633000","name":"Depreciation expenses","parent":"630000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"633001","name":"Depreciation — Computers and Equipment","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633002","name":"Depreciation — Furniture and Fixtures","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633003","name":"Depreciation — Vehicles","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633004","name":"Depreciation — Leasehold Improvements","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"634001","name":"Credit Loss Expense","parent":"630000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"700000","name":"Other income and expenses","parent":null,"type":"Expense","normal":"Debit","kind":"Group"},{"code":"710000","name":"Other income","parent":"700000","type":"Revenue","normal":"Credit","kind":"Group"},{"code":"711001","name":"Interest Income","parent":"710000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"712001","name":"Realized Foreign Exchange Gains","parent":"710000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"713001","name":"Unrealized Foreign Exchange Gains","parent":"710000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"720000","name":"Other expenses","parent":"700000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"721001","name":"Interest Expense","parent":"720000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"722001","name":"Realized Foreign Exchange Losses","parent":"720000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"723001","name":"Unrealized Foreign Exchange Losses","parent":"720000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"800000","name":"Income tax","parent":null,"type":"Expense","normal":"Debit","kind":"Group"},{"code":"810000","name":"Income tax expense","parent":"800000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"811001","name":"Income Tax Expense","parent":"810000","type":"Expense","normal":"Debit","kind":"Posting"}]');
 UPDATE tw_accounting_accounts SET has_auxiliary=true WHERE company_id=c AND code='112001';
 UPDATE tw_accounting_accounts SET has_auxiliary=true,auxiliary_source_code='112001' WHERE company_id=c AND code IN('112002','113001');
 aux:=tw_accounting_auxiliary_save_numbered(c,'112002',NULL,NULL,'AAIB',true,NULL,NULL,10);
 aux2:=tw_accounting_auxiliary_save_numbered(c,'112001',NULL,NULL,'Second bank',true,NULL,NULL,NULL);
 IF NOT EXISTS(SELECT 1 FROM tw_accounting_auxiliaries WHERE id=aux AND account_code='112001' AND number=10) OR NOT EXISTS(SELECT 1 FROM tw_accounting_auxiliaries WHERE id=aux2 AND account_code='112001' AND number=11) OR EXISTS(SELECT 1 FROM tw_accounting_auxiliaries WHERE company_id=c AND account_code IN('112002','113001')) THEN RAISE EXCEPTION 'Shared auxiliary list duplicated or lost sequence';END IF;
 blocked:=false;BEGIN UPDATE tw_accounting_accounts SET has_auxiliary=true,auxiliary_source_code='112002' WHERE company_id=c AND code='111001';EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Shared chain accepted';END IF;
 blocked:=false;BEGIN UPDATE tw_accounting_accounts SET auxiliary_source_code='112002' WHERE company_id=c AND code='112001';EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Circular shared list accepted';END IF;
 blocked:=false;BEGIN UPDATE tw_accounting_accounts SET active=false WHERE company_id=c AND code='112001';EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Shared source deactivated';END IF;
 q:=jsonb_build_array(jsonb_build_object('account','112001','auxiliaryId',aux,'description','Own list balance','debit','10','credit','0'),jsonb_build_object('account','112002','auxiliaryId',aux,'description','Shared list balance','debit','20','credit','0'),jsonb_build_object('account','311001','description','Capital balancing entry','debit','0','credit','30'));
 PERFORM tw_accounting_save_entry(j,c,'2026-01-15','QA','Shared auxiliary balances',NULL,'manual',q);PERFORM tw_accounting_post_journal(j,c,1);
 IF (SELECT count(DISTINCT account_code) FROM tw_accounting_journal_lines WHERE journal_id=j AND auxiliary_id=aux)<>2 THEN RAISE EXCEPTION 'Shared auxiliary identity not retained across GL accounts';END IF;
 r:=tw_accounting_statement(c,'2026-01-01','2026-12-31',NULL,'all',NULL,NULL,0,aux);
 IF jsonb_array_length(r->'accounts')<>2 OR (SELECT sum((x->>'closing')::numeric) FROM jsonb_array_elements(r->'accounts')x)<>30 THEN RAISE EXCEPTION 'Consolidated auxiliary statement incorrect';END IF;
 r:=tw_accounting_statement(c,'2026-01-01','2026-12-31','112002','all',NULL,NULL,0,aux);
 IF (r->'accounts'->0->>'closing')::numeric<>20 THEN RAISE EXCEPTION 'Independent GL auxiliary balance incorrect';END IF;
 blocked:=false;BEGIN UPDATE tw_accounting_accounts SET auxiliary_source_code=NULL,has_auxiliary=false WHERE company_id=c AND code='112002';EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Used shared configuration changed';END IF;
 PERFORM tw_accounting_mapping_save(c,'cash_bank','112002',aux,0);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(tw_accounting_mappings_read(c))x WHERE x->>'key'='cash_bank' AND x->>'account'='112002' AND x->>'auxiliary_id'=aux::text) THEN RAISE EXCEPTION 'Shared auxiliary mapping not saved';END IF;
 blocked:=false;BEGIN PERFORM tw_accounting_mapping_save(c,'agency_fee','511001',NULL,0);EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Wrong mapping account type accepted';END IF;
 r:=tw_accounting_create_client(c,'QA shared client '||inv,'QA shared client '||inv,'direct','EGP','EG');client:=(r->>'id')::uuid;account:=r->>'account';
 IF NOT EXISTS(SELECT 1 FROM clients WHERE id=client AND document_number=r->>'code') OR NOT EXISTS(SELECT 1 FROM tw_accounting_accounts WHERE company_id=c AND code=account AND client_id=client AND NOT has_auxiliary) THEN RAISE EXCEPTION 'Accounting client did not share Media identity and account';END IF;
 blocked:=false;BEGIN PERFORM tw_accounting_create_client(c,'QA shared client '||inv,'QA shared client '||inv,'direct','EGP','EG');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Duplicate client accepted';END IF;
 RESET ROLE;
 INSERT INTO invoices(id,document_number,client_id,issue_date,currency,subtotal,tax_amount,total,revenue_before_vat,revenue_vat_amount,revenue_after_vat) VALUES(inv,'QA-MAP-'||inv,client,'2026-01-15','EGP',120,16.8,136.8,120,16.8,136.8);
 INSERT INTO invoice_line_items(invoice_id,sort_order,description,quantity,unit_price,revenue_before_vat,revenue_vat_percent,metadata) VALUES(inv,1,'Saved component test',1,120,120,14,'{"accounting_components":{"assignment_revenue":100,"usage_rights_revenue":10,"agency_fee":10}}');
 UPDATE invoices SET amounts_finalized_at=now() WHERE id=inv;
 SET LOCAL ROLE authenticated;
 PERFORM tw_accounting_submit_invoice(inv,c);plan:=tw_accounting_invoice_mapping_preview(inv,c,account,'411001','231001');
 IF jsonb_array_length(plan->'lines')<>5 OR (plan->'components'->>'agency_fee')::numeric<>10 THEN RAISE EXCEPTION 'Mapped invoice components missing';END IF;
 PERFORM tw_accounting_mapping_save(c,'agency_fee','415001',NULL,0);
 blocked:=false;BEGIN PERFORM tw_accounting_post_mapped_invoice(inv,c,1,'2026-01-15',account,'411001','231001',1,plan,'{}');EXCEPTION WHEN serialization_failure THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Stale system mapping accepted';END IF;
 plan:=tw_accounting_invoice_mapping_preview(inv,c,account,'411001','231001');j:=tw_accounting_post_mapped_invoice(inv,c,1,'2026-01-15',account,'411001','231001',1,plan,'{}');
 IF NOT EXISTS(SELECT 1 FROM tw_accounting_journal_lines WHERE journal_id=j AND account_code='415001' AND credit=10 AND foreign_credit=10) OR (SELECT sum(debit-credit) FROM tw_accounting_journal_lines WHERE journal_id=j)<>0 THEN RAISE EXCEPTION 'Mapped invoice posting lost AF or balance';END IF;
 r:=tw_accounting_party_accounts(c,'vendor','',0);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rows')x WHERE NOT EXISTS(SELECT 1 FROM campaign_influencers ci JOIN campaign_lines l ON l.id=ci.campaign_line_id WHERE ci.influencer_id=(x->>'id')::uuid AND l.status<>'cancelled') AND NOT EXISTS(SELECT 1 FROM campaign_lines l WHERE l.metadata->'influencer_assignment'->>'influencer_id'=x->>'id' AND l.status<>'cancelled')) THEN RAISE EXCEPTION 'Discovery-only vendor leaked into accounting';END IF;
 RAISE NOTICE 'PASS: shared auxiliary identities, independent/consolidated balances, source/cycle/config guards, mapping validation and snapshots, AF/UR invoice split, shared client creation and vendor directory scope';
END $$;
ROLLBACK;
